)

func main() {
    fgaClient, err := NewSdkClient(&ClientConfiguration{
        ApiUrl: os.Getenv("FGA_API_URL"),
        StoreId: os.Getenv("FGA_STORE_ID"),
        AuthorizationModelId: os.Getenv("FGA_MODEL_ID"), // Optional; requests can override this.
    })
    if err != nil {
        panic(err)
    }

    body := ClientBatchCheckRequest{
      Checks: []ClientBatchCheckItem{
        ClientBatchCheckItem{
          User: "user:anne",
          Relation: "reader",
          Object: "document:budget",
          CorrelationId: "budget-reader",
        },
      },
    }
    options := BatchCheckOptions{
      MaxBatchSize: openfga.PtrInt32(50),
      MaxParallelRequests: openfga.PtrInt32(10),
    }
    data, err := fgaClient.BatchCheck(context.Background()).Body(body).Options(options).Execute()
    if err != nil {
        panic(err)
    }
    _ = data
}

